using System;
using EmberBastion;
class BossPriorityChecks {static int n;static void Check(bool v,string m){n++;if(!v)throw new Exception(m);}static Enemy Make(int id,int kind,double hp,double travel){return new Enemy{Id=id,Kind=kind,Gate=0,HP=hp,MaxHP=hp,Speed=0,Travel=travel,Position=new Point(192+travel,128)};}
 static void Main(){foreach(int kind in new[]{1,3}){var b=new Battle();Check(b.Place(kind,0)&&b.SetPriority(0,3),"priority accepted");var prep=Battle.RestorePreparation(b.SavePreparation());Check(prep.At(0).Priority==3,"preparation save");Check(prep.Start(),"start");Check(Battle.ImportCombat(prep.ExportCombat()).At(0).Priority==3&&prep.CopyCombat().At(0).Priority==3,"combat and checkpoint");prep.Enemies.Add(Make(100,0,500,180));prep.Enemies.Add(Make(101,4,5,80));prep.Step(1.0/60);Check(prep.Shots.Count>0&&prep.Shots[0].Target==101,"boss preferred despite low hp");
 var fallback=new Battle();Check(fallback.Place(kind,0)&&fallback.SetPriority(0,3)&&fallback.Start(),"fallback start");fallback.Enemies.Add(Make(100,0,500,180));fallback.Enemies.Add(Make(101,0,5,80));fallback.Step(1.0/60);Check(fallback.Shots.Count>0&&fallback.Shots[0].Target==100,"fallback to front");Check(!fallback.SetPriority(0,4),"invalid mode");}
 var melee=new Battle();Check(melee.Place(0,0)&&!melee.SetPriority(0,3),"melee cannot target");Console.WriteLine("PASS "+n+" boss priority, fallback and save checks");}}
